<section class="page-head"><div class="container"><div class="eyebrow">SUPPORT</div><h1>Centre d'aide</h1><p>Besoin d'orientation, de support technique ou d'un renseignement ?</p></div></section>
<section class="section"><div class="container support-grid"><div class="panel"><div class="panel-head"><div><h2>Créer un ticket</h2><p>Explique ton besoin clairement.</p></div></div><form method="post" action="/tickets/creer" class="form-stack"><input type="hidden" name="_csrf" value="<?= e($_SESSION['_csrf']) ?>"><label>Sujet<input name="subject" required maxlength="140" placeholder="Ex. Je ne sais pas quelle certification choisir"></label><label>Message<textarea name="message" required maxlength="2000" placeholder="Contexte, parcours actuel, objectif…"></textarea></label><button class="btn btn-primary">Envoyer le ticket</button></form></div><div class="panel"><div class="panel-head"><div><h2>Mes tickets</h2><p>Suivi de tes demandes.</p></div></div><?php foreach($tickets as $t): ?><div class="ticket-row"><div><b><?= e($t['subject']) ?></b><small><?= e(date('d/m/Y H:i',strtotime($t['created_at']))) ?></small></div><span class="chip <?= $t['status']==='resolu'?'success':'neutral' ?>"><?= e(str_replace('_',' ',ucfirst($t['status']))) ?></span></div><?php endforeach; if(!$tickets): ?><div class="empty-state"><p>Aucun ticket pour le moment.</p></div><?php endif; ?></div></div></section>
